{
  "predictors": [
    {
      "name": "Revenue Growth Stability",
      "construction": "Calculate the standard deviation of quarterly revenue growth rates over the past 5 years.",
      "rationale": "Firms with stable revenue growth may be better at managing operations and demand, leading to more predictable cash flows.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Employee Efficiency",
      "construction": "Compute the ratio of revenue to the number of employees from the most recent annual report.",
      "rationale": "Firms generating higher revenue per employee may be utilizing their workforce more efficiently, leading to better profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Capex Growth Consistency",
      "construction": "Measure the standard deviation of annual capital expenditure growth rates over the last 5 years.",
      "rationale": "Consistent investment in capital expenditures might indicate strategic planning and future growth potential.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Brand Investment Ratio",
      "construction": "Calculate the ratio of advertising expenses to total sales from the most recent annual reports.",
      "rationale": "Firms investing more in advertising may build stronger brands and customer loyalty, potentially boosting future sales.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Product Launch Frequency",
      "construction": "Count the number of new products launched by a firm over the past 3 years, as reported in press releases and product announcements.",
      "rationale": "Frequent product launches may indicate innovation and adaptability, enhancing competitive position.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "R&D Efficiency",
      "construction": "Calculate the ratio of R&D expenses to total revenue for the latest fiscal year.",
      "rationale": "A higher R&D efficiency ratio might signal successful innovation efforts translating into revenue.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "CEO Tenure",
      "construction": "Measure the number of years the current CEO has been in position as of the most recent annual report.",
      "rationale": "Longer CEO tenure can lead to consistent leadership and strategic direction, potentially enhancing firm stability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Diversity Ratio",
      "construction": "Calculate the ratio of the number of suppliers to cost of goods sold from the latest fiscal year.",
      "rationale": "Greater supplier diversity might reduce operational risk and lead to more favorable pricing and terms.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Satisfaction Index",
      "construction": "Estimate using publicly available measures such as employee reviews and satisfaction surveys from sources like Glassdoor.",
      "rationale": "Higher employee satisfaction can lead to improved productivity and reduced turnover costs, enhancing profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Commitment",
      "construction": "Count the number of new environmental initiatives announced over the past 3 years, from company reports and press releases.",
      "rationale": "Firms with more environmental initiatives may benefit from improved reputation and reduced regulatory risks.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
